create role anon; create role authenticated; create role service_role;
create table public.invoices (id uuid not null default gen_random_uuid(),
company_id uuid not null,
invoice_number text,
invoice_year integer default EXTRACT(year FROM now()),
progressive_number integer,
document_type text not null default 'invoice'::text,
status text not null default 'draft'::text,
client_id uuid,
client_company_name text not null,
client_vat_number text,
client_fiscal_code text,
client_address text,
client_city text,
client_zip text,
client_country text default 'IT'::text,
client_pec text,
client_sdi_code text,
client_email text,
issue_date date not null default CURRENT_DATE,
due_date date,
payment_date date,
subtotal numeric default 0,
tax_amount numeric default 0,
total numeric default 0,
paid_amount numeric default 0,
payment_method text,
payment_terms text,
payment_days integer,
bank_iban text,
order_id uuid,
quote_id uuid,
credited_invoice_id uuid,
notes text,
footer_text text,
external_id text,
external_provider text,
external_sync_at timestamp with time zone,
external_status text,
external_sdi_id text,
external_xml_url text,
pdf_url text,
pdf_generated_at timestamp with time zone,
created_by uuid,
created_at timestamp with time zone default now(),
updated_at timestamp with time zone default now(),
last_synced_at timestamp with time zone,
sede_id uuid,
deleted_at timestamp with time zone,
deleted_by uuid,
order_match_origine text,
cliente_collegato_at timestamp with time zone,
cliente_collegato_esito text,
rif_fattura_numero text,
rif_fattura_data date);
create table public.invoice_lines (id uuid not null default gen_random_uuid(),
invoice_id uuid not null,
sort_order integer default 0,
description text not null,
product_code text,
unit text default 'pz'::text,
quantity numeric not null default 1,
unit_price numeric not null default 0,
discount_percent numeric default 0,
tax_rate numeric not null default 22,
tax_nature text,
line_net numeric not null default 0,
line_tax numeric not null default 0,
line_gross numeric not null default 0,
created_at timestamp with time zone default now());
