iban_pagamento text,
bic_pagamento text,
nome_banca text,
intestatario_conto text,
riferimenti_ordine jsonb default '[]'::jsonb,
riferimenti_ddt jsonb default '[]'::jsonb,
documento_correlato_id uuid,
cig text,
cup text,
codice_commessa_convenzione text,
ddt_causale_trasporto text,
