sdi_file_p7m_url text,
altra_ritenuta boolean default false,
altra_ritenuta_tipo text,
altra_ritenuta_aliquota numeric,
altra_ritenuta_causale text,
altra_ritenuta_importo numeric,
rivalsa_inps boolean default false,
rivalsa_tipo text,
rivalsa_aliquota numeric,
rivalsa_importo numeric,
esigibilita_iva text default 'I'::text,
allega_pdf_sdi boolean default true,
emesso_in_seguito_a text,
version integer not null default 1,
sdi_identificativo text);
create table public.fatture_ricevute(id uuid default gen_random_uuid(), company_id uuid, sdi_id_trasmissione text, xml_sha256 text);
create unique index idx_fatture_ricevute_sdi_unique on public.fatture_ricevute(sdi_id_trasmissione) where sdi_id_trasmissione is not null;
create unique index ux_fatture_ricevute_impronta on public.fatture_ricevute(company_id,xml_sha256) where xml_sha256 is not null;
create table public.fiscalita_periodi(company_id uuid,mese date,stato text);

alter table fatture_ricevute add column data_fattura date, add column data_ricezione_sdi timestamptz, add column tipo_documento text, add column imponibile_totale numeric, add column iva_totale numeric, add column riepilogo_iva jsonb, add column aliquota_reverse_charge numeric, add column stato text;
create function public.user_can_access_company(uuid) returns boolean language sql stable as $$ select coalesce(current_setting('test.company',true),'')=$1::text $$;
create function public.num_da_json(text) returns numeric language sql immutable as $$ select coalesce(nullif($1,''),'0')::numeric $$;
create function public.data_detrazione_iva(date,timestamptz) returns date language sql immutable as $$ select coalesce($2::date,$1) $$;
